alter table public.profiles   add column if not exists phone text,   add column if not exists phone_verified_at timestamptz,   add column if not exists whatsapp text,   add column if not exists contact_number text;  alter table public.promo_banners   add column if not exists badge text not null default '',   add column if not exists highlight text not null default '',   add column if not exists secondary_cta_label text,   add column if not exists secondary_cta_url text,   add column if not exists accent_color text not null default '#55c8f5';  alter table public.promo_banners   add constraint promo_banners_accent_color_hex check (accent_color ~ '^#[0-9A-Fa-f]{6}$');  create table if not exists public.newsletter_subscribers (   id uuid primary key default gen_random_uuid(),   email text not null check (email = lower(btrim(email)) and email ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'),   consented_at timestamptz not null default now(),   confirmed_at timestamptz,   confirmation_token_hash text,   unsubscribe_token_hash text not null,   unsubscribed_at timestamptz,   created_at timestamptz not null default now(),   updated_at timestamptz not null default now(),   constraint newsletter_confirmation_hash_hex check (confirmation_token_hash is null or confirmation_token_hash ~ '^[0-9a-f]{64}$'),   constraint newsletter_unsubscribe_hash_hex check (unsubscribe_token_hash ~ '^[0-9a-f]{64}$') ); create unique index if not exists newsletter_subscribers_email_lower_key on public.newsletter_subscribers (lower(email)); create unique index if not exists newsletter_subscribers_confirmation_hash_key on public.newsletter_subscribers (confirmation_token_hash) where confirmation_token_hash is not null; create unique index if not exists newsletter_subscribers_unsubscribe_hash_key on public.newsletter_subscribers (unsubscribe_token_hash); create index if not exists newsletter_subscribers_confirmed_idx on public.newsletter_subscribers (created_at desc) where confirmed_at is not null and unsubscribed_at is null; alter table public.newsletter_subscribers enable row level security; grant select, insert, update, delete on public.newsletter_subscribers to authenticated; create policy "admins manage newsletter subscribers" on public.newsletter_subscribers for all to authenticated   using (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid())))   with check (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid())));  create table if not exists public.newsletter_campaigns (   id uuid primary key default gen_random_uuid(),   subject text not null check (char_length(subject) between 3 and 180),   body text not null check (char_length(body) between 1 and 20000),   recipient_count integer not null check (recipient_count >= 0),   sent_by uuid not null references auth.users(id) on delete restrict,   sent_at timestamptz not null default now() ); alter table public.newsletter_campaigns enable row level security; grant select on public.newsletter_campaigns to authenticated; grant insert on public.newsletter_campaigns to authenticated; create policy "admins read newsletter campaigns" on public.newsletter_campaigns for select to authenticated   using (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid()))); create policy "admins create newsletter campaigns" on public.newsletter_campaigns for insert to authenticated   with check (sent_by = (select auth.uid()) and exists (select 1 from public.admin_users a where a.user_id = (select auth.uid())));  create or replace function public.newsletter_subscribe(p_email text, p_confirmation_token_hash text, p_unsubscribe_token_hash text) returns boolean language plpgsql security definer set search_path = '' as $$ declare v_id uuid; begin   if p_email is null or char_length(btrim(p_email)) > 254      or lower(btrim(p_email)) !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'      or p_confirmation_token_hash !~ '^[0-9a-f]{64}$'      or p_unsubscribe_token_hash !~ '^[0-9a-f]{64}$' then     raise exception 'Invalid newsletter subscription' using errcode = '22023';   end if;   insert into public.newsletter_subscribers as existing (email, confirmation_token_hash, unsubscribe_token_hash)   values (lower(btrim(p_email)), p_confirmation_token_hash, p_unsubscribe_token_hash)   on conflict (lower(email)) do update set     confirmation_token_hash = excluded.confirmation_token_hash,     unsubscribe_token_hash = excluded.unsubscribe_token_hash,     consented_at = now(), unsubscribed_at = null, updated_at = now()   where existing.confirmed_at is null or existing.unsubscribed_at is not null   returning id into v_id;   return v_id is not null; end; $$; revoke all on function public.newsletter_subscribe(text,text,text) from public, anon, authenticated; grant execute on function public.newsletter_subscribe(text,text,text) to anon, authenticated;  create or replace function public.newsletter_confirm(p_confirmation_token_hash text) returns boolean language plpgsql security definer set search_path = '' as $$ begin   if p_confirmation_token_hash is null or p_confirmation_token_hash !~ '^[0-9a-f]{64}$' then return false; end if;   update public.newsletter_subscribers set confirmed_at = now(), confirmation_token_hash = null, updated_at = now()   where confirmation_token_hash = p_confirmation_token_hash and unsubscribed_at is null;   return found; end; $$; revoke all on function public.newsletter_confirm(text) from public, anon, authenticated; grant execute on function public.newsletter_confirm(text) to anon, authenticated;  create or replace function public.newsletter_unsubscribe(p_unsubscribe_token_hash text) returns boolean language plpgsql security definer set search_path = '' as $$ begin   if p_unsubscribe_token_hash is null or p_unsubscribe_token_hash !~ '^[0-9a-f]{64}$' then return false; end if;   update public.newsletter_subscribers set unsubscribed_at = now(), confirmation_token_hash = null, updated_at = now()   where unsubscribe_token_hash = p_unsubscribe_token_hash and unsubscribed_at is null;   return found; end; $$; revoke all on function public.newsletter_unsubscribe(text) from public, anon, authenticated; grant execute on function public.newsletter_unsubscribe(text) to anon, authenticated;  create or replace function public.validate_checkout_coupon(p_code text, p_subtotal numeric) returns jsonb language plpgsql security definer set search_path = '' as $$ declare v_coupon public.coupons%rowtype; v_discount numeric(10,2); begin   if (select auth.uid()) is null then raise exception 'Authentication required' using errcode = '28000'; end if;   if p_subtotal is null or p_subtotal <= 0 then return jsonb_build_object('valid', false, 'message', 'Add products before applying a code.'); end if;   select * into v_coupon from public.coupons c   where c.code = upper(btrim(p_code)) and c.is_active and (c.expires_at is null or c.expires_at > now());   if not found then return jsonb_build_object('valid', false, 'message', 'This discount code is invalid or expired.'); end if;   if v_coupon.minimum is not null and p_subtotal < v_coupon.minimum then     return jsonb_build_object('valid', false, 'message', 'Your order does not meet this codeΓÇÖs minimum.');   end if;   if v_coupon.usage_limit is not null and v_coupon.uses >= v_coupon.usage_limit then     return jsonb_build_object('valid', false, 'message', 'This discount code has reached its use limit.');   end if;   if exists (select 1 from public.coupon_usages u where u.coupon_id = v_coupon.id and u.user_id = (select auth.uid())) then     return jsonb_build_object('valid', false, 'message', 'You have already used this discount code.');   end if;   v_discount := case when v_coupon.discount_type = 'percentage' then p_subtotal * v_coupon.discount_value / 100 else v_coupon.discount_value end;   v_discount := least(p_subtotal, v_discount, coalesce(v_coupon.max_discount, p_subtotal));   return jsonb_build_object('valid', true, 'code', v_coupon.code, 'discount', v_discount, 'discount_type', v_coupon.discount_type, 'discount_value', v_coupon.discount_value); end; $$; revoke all on function public.validate_checkout_coupon(text,numeric) from public, anon; grant execute on function public.validate_checkout_coupon(text,numeric) to authenticated;  create or replace function private.create_checkout_order(p_items jsonb, p_coupon_code text) returns jsonb language plpgsql security definer set search_path = '' as $$ declare   v_user_id uuid := (select auth.uid()); v_email text; v_coupon public.coupons%rowtype;   v_coupon_id uuid; v_order_id uuid; v_subtotal numeric(10,2); v_discount numeric(10,2); v_coupon_discount numeric(10,2); v_total numeric(10,2); begin   if v_user_id is null then raise exception 'Authentication required' using errcode = '28000'; end if;   if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) not between 1 and 50 then raise exception 'Cart must contain 1 to 50 items' using errcode = '22023'; end if;   if exists (select 1 from jsonb_to_recordset(p_items) as item(slug text, quantity integer) where item.slug is null or item.slug = '' or item.quantity not between 1 and 50) then raise exception 'Cart contains invalid items' using errcode = '22023'; end if;   if exists (select 1 from (select sum(item.quantity) quantity from jsonb_to_recordset(p_items) as item(slug text, quantity integer) group by item.slug) q where q.quantity > 50) then raise exception 'Product quantity exceeds the limit' using errcode = '22023'; end if;   select u.email into v_email from auth.users u where u.id = v_user_id;   if v_email is null then raise exception 'Account email is required' using errcode = '22023'; end if;   if nullif(btrim(p_coupon_code), '') is not null then     select * into v_coupon from public.coupons c where c.code = upper(btrim(p_coupon_code)) and c.is_active and (c.expires_at is null or c.expires_at > now()) for update;     if not found then raise exception 'Discount code is invalid or expired' using errcode = '22023'; end if;     if v_coupon.usage_limit is not null and v_coupon.uses >= v_coupon.usage_limit then raise exception 'Discount code has reached its use limit' using errcode = '22023'; end if;     if exists (select 1 from public.coupon_usages u where u.coupon_id = v_coupon.id and u.user_id = v_user_id) then raise exception 'Discount code already used by this account' using errcode = '22023'; end if;     v_coupon_id := v_coupon.id;   end if;   with requested as (     select item.slug, sum(item.quantity)::integer quantity from jsonb_to_recordset(p_items) as item(slug text, quantity integer) group by item.slug   ), priced as (     select p.id, p.name, p.price, requested.quantity, best.offer_id, coalesce(best.amount, 0)::numeric(10,2) discount_per_unit     from requested join public.products p on p.slug = requested.slug and p.is_active     left join lateral (       select o.id offer_id, least(p.price, case when o.discount_type = 'percentage' then p.price * o.discount_value / 100 else o.discount_value end) amount       from public.offers o where o.is_active and o.starts_at <= now() and o.ends_at >= now()         and (o.product_id = p.id or o.game_id = p.game_id or o.category_id = p.category_id)       order by amount desc, o.sort_order, o.ends_at limit 1     ) best on true   ), totals as (     select (select count(*) from requested) requested_count, count(*) product_count,       coalesce(sum(priced.price * priced.quantity),0)::numeric(10,2) subtotal,       coalesce(sum(priced.discount_per_unit * priced.quantity),0)::numeric(10,2) offer_discount     from priced   ), couponed as (     select totals.*, case       when v_coupon_id is null then 0::numeric       when v_coupon.minimum is not null and totals.subtotal < v_coupon.minimum then null::numeric       else least(greatest(0, totals.subtotal - totals.offer_discount),         case when v_coupon.discount_type = 'percentage' then (totals.subtotal - totals.offer_discount) * v_coupon.discount_value / 100 else v_coupon.discount_value end,         coalesce(v_coupon.max_discount, totals.subtotal))     end::numeric(10,2) coupon_discount from totals   ), created as (     insert into public.orders (user_id, email, subtotal, discount, total, coupon_id)     select v_user_id, v_email, subtotal, offer_discount + coupon_discount, greatest(0, subtotal - offer_discount - coupon_discount), v_coupon_id     from couponed where requested_count > 0 and requested_count = product_count and coupon_discount is not null returning id   ), items_created as (     insert into public.order_items (order_id, product_id, product_name, quantity, unit_price, line_total, offer_id)     select created.id, priced.id, priced.name, priced.quantity, greatest(0,priced.price-priced.discount_per_unit)::numeric(10,2),       (greatest(0,priced.price-priced.discount_per_unit)*priced.quantity)::numeric(10,2), priced.offer_id     from created cross join priced returning 1   ), usage_created as (     insert into public.coupon_usages (coupon_id,user_id,order_id,discount_amount)     select v_coupon_id,v_user_id,created.id,couponed.coupon_discount from created cross join couponed where v_coupon_id is not null returning 1   ), coupon_updated as (     update public.coupons c set uses=c.uses+1 from created where v_coupon_id is not null and c.id=v_coupon_id returning c.id   ), payment_created as (     insert into public.payments (order_id,provider,status,amount,currency)     select created.id,'pending','INITIATED',greatest(0,couponed.subtotal-couponed.offer_discount-couponed.coupon_discount),'USD'     from created cross join couponed returning id   )   select created.id,couponed.subtotal,couponed.offer_discount+couponed.coupon_discount,     greatest(0,couponed.subtotal-couponed.offer_discount-couponed.coupon_discount)   into v_order_id,v_subtotal,v_discount,v_total from created cross join couponed;   if v_order_id is null then raise exception 'One or more cart products are unavailable or this code does not meet its minimum' using errcode = '22023'; end if;   return jsonb_build_object('id',v_order_id,'subtotal',v_subtotal,'discount',v_discount,'total',v_total); end; $$; revoke all on function private.create_checkout_order(jsonb,text) from public, anon, authenticated, service_role; grant execute on function private.create_checkout_order(jsonb,text) to authenticated; create or replace function public.create_checkout_order(p_items jsonb, p_coupon_code text) returns jsonb language sql security invoker set search_path = '' as $$ select private.create_checkout_order(p_items,p_coupon_code); $$; revoke all on function public.create_checkout_order(jsonb,text) from public, anon; grant execute on function public.create_checkout_order(jsonb,text) to authenticated;  create or replace view public.product_sales with (security_invoker = false) as select oi.product_id, sum(oi.quantity)::bigint as units_sold from public.order_items oi join public.orders o on o.id=oi.order_id where o.status in ('PAID','PROCESSING','COMPLETED') group by oi.product_id; revoke all on public.product_sales from public; grant select on public.product_sales to anon, authenticated;  notify pgrst, 'reload schema';